52	/* 我们自己的发送缓冲池：最多 4 个在途帧，每帧按 1600 字节 L2CAP 载荷算 */
53	
54	NET_BUF_POOL_FIXED_DEFINE(pw_pan_pool, 4, BT_L2CAP_BUF_SIZE(1600), 8, NULL);
