111	static void pan_fail(const char *why)
112	{
113	  snprintf(g_pan.last_err, sizeof(g_pan.last_err), "%s", why);
114	  g_pan.state = PW_PAN_FAIL;
115	  printf("[pan] FAIL: %s\n", why);
