118	/* ---------------------------------------------------------------------------
119	 * 发送
120	 * ------------------------------------------------------------------------- */
121	
122	static int pan_send_raw(const uint8_t *data, uint32_t len)
123	{
124	  struct net_buf *buf;
125	  int             err;
126	
127	  if (!g_pan.conn || len == 0 || len > PW_PAN_FRAME_MAX)
128	    {
129	      return -EINVAL;
130	    }
131	
132	  /* 注意：bt_l2cap_create_pdu() 只在 subsys/bluetooth/host/l2cap_internal.h
133	   * 里（应用侧拿不到），所以这里用官方给应用侧的等价写法：
134	   * net_buf_alloc() + net_buf_reserve(BT_L2CAP_CHAN_SEND_RESERVE)。
135	   * 池大小 BT_L2CAP_BUF_SIZE(1600) 已含 ACL/L2CAP 头，够留这段预留。
136	   */
137	
138	  buf = net_buf_alloc(&pw_pan_pool, K_FOREVER);
139	  if (buf == NULL)
140	    {
141	      return -ENOMEM;
142	    }
143	
144	  net_buf_reserve(buf, BT_L2CAP_CHAN_SEND_RESERVE);
145	
