247	/* ---------------------------------------------------------------------------
248	 * 收帧（L2CAP 回调，跑在 BT host 的 rx 线程上）
249	 * ------------------------------------------------------------------------- */
250	
251	static int pan_on_frame(const uint8_t *data, uint32_t len)
252	{
253	  struct pw_bnep_hdr hdr;
254	  int32_t            rc;
255	
256	  rc = pw_bnep_parse(data, len, &hdr);
257	  if (rc < 0)
258	    {
259	      g_pan.rx_drop++;
260	      return 0;
261	    }
262	
263	  if (hdr.type == PW_BNEP_CONTROL)
264	    {
265	      switch (hdr.ctl)
266	        {
267	          case PW_BNEP_CTL_SETUP_RSP:
268	            {
269	              uint16_t code = 0xffff;
270	              if (pw_bnep_parse_setup_rsp(data, len, &code) == 0)
271	                {
272	                  if (code == 0)
273	                    {
274	                      printf("[pan] BNEP setup rsp=0x0000 ok\n");
275	                      g_pan.state = PW_PAN_FILTER;
276	                      pan_send_filter();
277	                    }
278	                  else
279	                    {
280	                      printf("[pan] BNEP setup rsp=0x%04x -> fail\n", code);
281	                      pan_fail("bnep setup rejected");
282	                    }
283	                }
284	            }
285	            break;
286	
287	          case PW_BNEP_CTL_FILTER_RSP:
288	            {
289	              uint16_t code = 0xffff;
290	              if (pw_bnep_parse_filter_rsp(data, len, &code) == 0)
291	                {
292	                  if (code == 0)
293	                    {
294	                      printf("[pan] filter ok -> UP\n");
295	                      g_pan.state = PW_PAN_UP;
296	                    }
297	                  else
298	                    {
299	                      printf("[pan] filter rsp=0x%04x -> fail\n", code);
300	                      pan_fail("filter rejected");
301	                    }
302	                }
303	            }
304	            break;
305	
306	          default:
307	            printf("[pan] control ctl=0x%02x len=%u (ignored)\n", hdr.ctl,
308	                   (unsigned)hdr.paylen);
309	            break;
310	        }
311	
312	      return 0;
313	    }
314	
315	  if (hdr.eth == NULL || hdr.ethlen == 0)
316	    {
317	      g_pan.rx_drop++;
318	      return 0;
319	    }
320	
321	  if (g_pan.tunfd < 0)
322	    {
323	      g_pan.rx_drop++;
324	      return 0;
325	    }
326	
327	  if (write(g_pan.tunfd, hdr.eth, hdr.ethlen) != (ssize_t)hdr.ethlen)
328	    {
329	      g_pan.rx_drop++;
330	      return 0;
331	    }
332	
333	  g_pan.rx_frames++;
334	  return 0;
335	}
336	
337	static int pan_l2cap_recv(struct bt_l2cap_chan *chan, struct net_buf *buf)
338	{
339	  uint8_t  frame[PW_PAN_FRAME_MAX];
340	  uint32_t total;
341	  uint32_t off = 0;
342	  struct net_buf *f;
343	
344	  (void)chan;
345	
346	  total = net_buf_frags_len(buf);               /* [已核实] net_buf.h:2711 static inline size_t */
347	  if (total > sizeof(frame))
348	    {
349	      g_pan.rx_drop++;
350	      net_buf_unref(buf);
351	      return 0;
352	    }
353	
354	  /* 逐片拷贝：收到的 PDU 各片 data 都指向本片载荷起点 */
355	
356	  for (f = buf; f != NULL && off < total; f = f->frags)
357	    {
358	      uint32_t n = f->len;
359	      if (n > total - off)
360	        {
361	          n = total - off;
362	        }
363	
364	      memcpy(&frame[off], f->data, n);
365	      off += n;
366	    }
367	
368	  net_buf_unref(buf);
369	
370	  if (off != total)
371	    {
372	      g_pan.rx_drop++;
373	      return 0;
374	    }
375	
376	  return pan_on_frame(frame, total);
377	}
