539	  pthread_attr_setinheritsched(&attr, PTHREAD_EXPLICIT_SCHED);
540	
541	  err = pthread_create(&g_pan.thread, &attr, pan_tun_thread, NULL);
542	  pthread_attr_destroy(&attr);
543	  if (err != 0)
544	    {
